import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p45_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_cat_cuda(torch::Tensor a, torch::Tensor b);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_cat", &fused_cat_cuda, "Fused NCHW channel concatenation (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_cat_kernel(
    float* __restrict__ out,
    const float* __restrict__ a,
    const float* __restrict__ b,
    int N, int C_a, int C_b, int spatial
) {
    int C_out = C_a + C_b;
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * C_out * spatial;
    if (idx >= total) return;

    int hw = (int)(idx % spatial);
    int c  = (int)((idx / (long long)spatial) % C_out);
    int n  = (int)(idx / ((long long)C_out * spatial));

    if (c < C_a) {
        out[idx] = a[(long long)n * C_a * spatial + (long long)c * spatial + hw];
    } else {
        int c_b = c - C_a;
        out[idx] = b[(long long)n * C_b * spatial + (long long)c_b * spatial + hw];
    }
}

torch::Tensor fused_cat_cuda(torch::Tensor a, torch::Tensor b) {
    a = a.contiguous();
    b = b.contiguous();
    TORCH_CHECK(a.dim() == 4 && b.dim() == 4,
                "fused_cat: inputs must be 4-D NCHW tensors");
    TORCH_CHECK(a.size(0) == b.size(0) && a.size(2) == b.size(2) && a.size(3) == b.size(3),
                "fused_cat: N, H, W dimensions must match");
    TORCH_CHECK(a.scalar_type() == torch::kFloat32 && b.scalar_type() == torch::kFloat32,
                "fused_cat: only float32 inputs are supported");

    int N       = (int)a.size(0);
    int C_a     = (int)a.size(1);
    int C_b     = (int)b.size(1);
    int H       = (int)a.size(2);
    int W       = (int)a.size(3);
    int spatial = H * W;

    auto out = torch::empty({N, C_a + C_b, H, W}, a.options());

    long long total   = (long long)N * (C_a + C_b) * spatial;
    int       threads = 256;
    long long blocks  = (total + threads - 1) / threads;

    fused_cat_kernel<<<(int)blocks, threads>>>(
        out.data_ptr<float>(),
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        N, C_a, C_b, spatial
    );

    return out;
}
# <<<END_IMPROVE>>>
